import{d as c,C as t,o as u,c as m,j as a,a as s,E as r,a3 as x}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第十九章","description":"从三组绝弃的激烈表述，读到见素抱朴、少私寡欲的归依。","frontmatter":{"title":"道德经第十九章","description":"从三组绝弃的激烈表述，读到见素抱朴、少私寡欲的归依。","category":"guide","aliases":["道德经第十九章","老子第十九章","dao de jing chapter 19"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-19.md","filePath":"daoism/dao-de-jing/chapter-19.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-19.md"},_=c({...p,setup(b){const o=[{id:"three-radical-renunciations",label:"绝圣弃智，民利百倍",showLabel:!0,sentences:[["绝",{text:"圣",glossary:"sheng"},"弃",{text:"智",glossary:"zhi"},"，民利百倍；"],["绝",{text:"仁",glossary:"ren"},"弃",{text:"义",glossary:"yi"},"，民复",{text:"孝慈",glossary:"xiaoci"},"；"],["绝",{text:"巧",glossary:"qiao"},"弃利，盗贼无有。"]],note:["【白话】断绝被标举的圣与智，百姓会获得很大的利益；断绝被标举的仁与义，百姓便回复孝慈；断绝机巧与逐利，盗贼便不再产生。这是原文有意采用的激烈表述，须接下文读其所归。","【王弼注择要】「圣智，才之善也。仁义，人之善也。巧利，用之善也。」王弼先承认这些名目各有所善，随后才说明只直说绝弃，文意还不足。","【读法】本页依注从绝弃人为标立、机巧逐求的方向理解，不把三句改写成消灭知识、关爱与所有技能的命令。百倍与盗贼无有是原文的强化表达，不作可直接测算的治理效果。"]},{id:"words-need-a-positive-ground",label:"此三者以为文不足",showLabel:!0,sentences:[["此三者以为",{text:"文",glossary:"wen"},"不足，故令有所",{text:"属",glossary:"shu"},"："]],note:["【白话】这三项只作为这样的文辞表述，还不足以说明旨意，所以要使人有所归依。下文素、朴、少私、寡欲才给出所归的方向。","【王弼注择要】「而直云绝，文甚不足。」又说「不令之有所属，无以见其指」。注提醒，不能把绝弃口号从后面的归依中截断。","【读法】文依此处古注取表述、文辞义，不只理解成一切文化或装饰。属本页读 shǔ，作归属、依归；三个否定之后，必须问人如何安顿。"]},{id:"plainness-and-fewer-desires",label:"见素抱朴，少私寡欲",showLabel:!0,sentences:[[{text:"见",glossary:"xian"},{text:"素",glossary:"su"},"抱",{text:"朴",glossary:"pu"},"，",{text:"少私寡欲",glossary:"shaosiguayu"},"，"]],note:["【白话】显出未加染饰的本色，守住未经雕琢的质朴，减少一己私求与过度欲望。这是三组绝弃之后要回到的生活取向。","【王弼注择要】「属之于素朴寡欲。」注将所归之处明确落在素朴与寡欲，不让绝弃停成无所依凭的破坏。","【读法】见本页读 xiàn，取显现本色义；朴沿用未经雕琢木材的譬喻。少私寡欲不等于取消基本需要，也不能仅凭衣着器物朴素就断定一个人没有私求。"]},{id:"learning-and-anxiety",label:"绝学无忧",showLabel:!0,sentences:[[{text:"绝学",glossary:"juexue"},"无忧。"]],note:["【白话】断绝那种不断追逐增益、智巧与外在评价的学，便不再有由此生出的忧扰。本页循王弼续文解释，限定这里所说的学与忧。","【王弼注择要】王弼在接续这一句的注文中说「学求益所能而进其智者也」，又说「自然已足，益之则忧」。所反省的是自然已足之后仍一味求益的方向。","【读法】本站将本句留在第十九章末，所据录文将其接在下一组唯之与阿之前。可连到第二十章读，不把它单独当作停止教育、拒绝学习的格言。"]}],n=[{id:"sheng",term:"圣",sense:1},{id:"zhi",term:"智",sense:1},{id:"ren",term:"仁",sense:1,context:"王弼先承认仁义为人之善；本页由标立与造作解释绝弃的对象。"},{id:"yi",term:"义",sense:1},{id:"xiaoci",term:"孝慈",sense:1},{id:"qiao",term:"巧",sense:1},{id:"wen",term:"文",sense:1},{id:"shu",term:"属",sense:1,pinyin:"shǔ"},{id:"xian",term:"见",sense:1,pinyin:"xiàn",context:"本页取显现本色义；见素的其他训释不在此混写。"},{id:"su",term:"素",sense:1},{id:"pu",term:"朴",sense:1},{id:"shaosiguayu",term:"少私寡欲",sense:1},{id:"juexue",term:"绝学",sense:1}];return(g,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第十九章",tabindex:"-1"},[s("道德经第十九章 "),a("a",{class:"header-anchor",href:"#道德经第十九章","aria-label":'Permalink to "道德经第十九章"'},"​")],-1)),r(i,{title:"三次绝弃之后，人要归向哪里？",summary:"本章的锋芒在绝圣、绝仁、绝巧，但它没有停在否定：文不足、有所属接出素朴与寡欲。把前后连起，才能避免将激烈语言读成对学习、关爱和技能的一概拒绝。",points:[{label:"先读",text:"三组绝弃各自承诺恢复什么？"},{label:"再辨",text:"为什么说三句作为文辞仍然不足？"},{label:"后想",text:"素朴与寡欲怎样成为可实践的所归？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[s("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),r(l,{sections:o,glossary:n,tone:"ink",density:"comfortable","aria-label":"《道德经》第十九章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[s("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"绝圣弃智，民利百倍。",tone:"先留住锋芒",guide:"原文确有激烈的绝弃语气，不能全磨成温和劝善；但王弼同时承认圣智为才之善，解释需把这种张力留住。"},{text:"此三者以为文不足，故令有所属。",tone:"否定尚未完成",guide:"只知道反对什么，还没有交代怎样生活。文不足引出所归，成为理解前三句的章内约束。"},{text:"见素抱朴，少私寡欲。",tone:"落到所归",guide:"少些染饰、私求与过度追逐，比另立一套圣智身份供人竞争，更接近本章给出的方向。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[s("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=x('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么三组绝弃不能与后文分开" tabindex="-1">象：为什么三组绝弃不能与后文分开？ <a class="header-anchor" href="#象-为什么三组绝弃不能与后文分开" aria-label="Permalink to &quot;象：为什么三组绝弃不能与后文分开？&quot;">​</a></h3><p>前三句用强烈的否定指向百姓获利、回复孝慈、盗贼不生，后文却立即说文不足，需要有所属。章内已经提示：若没有素朴寡欲的归依，单说绝弃还不能充分表达意思。</p><h3 id="理-王弼承认圣智仁义之善-怎样理解绝弃" tabindex="-1">理：王弼承认圣智仁义之善，怎样理解绝弃？ <a class="header-anchor" href="#理-王弼承认圣智仁义之善-怎样理解绝弃" aria-label="Permalink to &quot;理：王弼承认圣智仁义之善，怎样理解绝弃？&quot;">​</a></h3><p>他先分别说明才之善、人之善、用之善，再说直云绝不足见其旨。这里并非简单断言这些能力与善行全无价值，而是将其放回素朴寡欲的根本取向。本页据此解释造作与逐名的问题，同时保留原文比这一解释更激烈的语气。</p><h3 id="用-减少外在追逐-会不会失去实际能力" tabindex="-1">用：减少外在追逐，会不会失去实际能力？ <a class="header-anchor" href="#用-减少外在追逐-会不会失去实际能力" aria-label="Permalink to &quot;用：减少外在追逐，会不会失去实际能力？&quot;">​</a></h3><p>去掉的是为了身份、竞争和私求而不断加码的部分，不应把需要的知识、技能和照顾一并丢掉。现代应用时可以检查一项投入的真实用途；若取消它会伤及基本生活与责任，就需要重新判断，而不能凭绝学二字定夺。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>清理一项多余的证明。</strong> 学习或工作中，可以回看哪些安排是在解决实际问题，哪些只是证明自己更懂、更高明。减少无效的展示与比较，可能让必要的学习重新有方向。</p><p><strong>让简朴服务真实需要。</strong> 简化流程、物品或目标之后，应看理解是否更清楚、协作是否更顺、基本需要是否得到照顾。若只有删减的姿态，却使人无所依凭，正值得回看有所属这一句。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我希望放下的一项追逐，放下后准备归向什么？它会帮助我更真实地学习、照顾与行动，还是只留下一个清高的姿态？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本页保留本站「此三者以为文不足」「故令有所属」的正文；王弼注另用「此三者以为文而未足」「故令人有所属」申说，不将注文补字混入正文。</li><li>见素本页读 xiàn sù、取显现本色义；文不足依王弼直云绝尚不足见旨的解释，不直接讲成反对一切文化。</li><li>本站「绝学无忧」位于第十九章末；所据录文在素朴寡欲注文后另起「绝学无忧，唯之与阿……」。本页保留现有页面归属，第二十章承接说明，避免两页重复录入或漏句。</li><li>绝学段的古注节引属于接续「唯之与阿」的注文，来源定位延至 013a；不冒充只在第十九章前三句下的注语。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，012a–013a</a>；续读<a href="/Dao/daoism/dao-de-jing/chapter-20">第二十章</a>。</p>',15))])}}});export{y as __pageData,_ as default};
